  rw: {
    badge: 'KWIZIRIKA NO KWISHYURA (QADAA)',
    title: 'Kwiyiriza no kubabarirwa:\nkwishyura (Qadaa)',
    metaDuration: 'Iminota 6 yo gusoma',
    metaType: 'Ibibazo n’ibisubizo',
    metaLevel: 'Ku batangiye',
    metaValidated: 'Ibikubiyemo byasuzumwe',
    intro: 'Uko n’igihe cyo kwishyura iminsi y’isiyamu watakaje, ku muvuduko wawe nta kwicira urubanza.',
    disclaimerTitle: 'Amakuru y’ingenzi',
    disclaimerText: 'Ibi bikubiyemo ni iby’inyigisho gusa. Ibibazo by’idini bigomba kwemezwa n’abahanga babifitiye ububasha. AWA ntitanga fatwa cyangwa imyanzuro y’idini yihariye.',
    contentsTitle: 'Muri iyi nkuru',
    topics: [
      'Ni ryari wishyura iminsi watakaje?',
      'Igihe gisanzwe: mbere ya Ramadan ikurikira',
      'Inda no konsa',
      'Ibyingenzi byo kwibuka',
    ],
    section1Body: 'Qadaa ni ukwishyura nyuma iminsi y’isiyamu yatakaye muri Ramadan — cyane cyane kubera imihango. Iyi minsi igomba kwishyurwa kuko isiyamu ya Ramadan ikomeza kuba inkingi y’ukwezi, kandi iminsi ihagarikwa n’imihango ibarwa nk’iyo ugomba, bitavuze ko ari ikosa ryawe.',
    section1Body2: 'Kwishyura muri rusange bishobora gutangira Ramadan irangiye, iyo imiterere yawe ibyemeye. Ushobora gutegura iyi minsi ku muvuduko wawe: bamwe bahitamo kuyihuriza hamwe nyuma ya Ramadan, abandi bakayigabanya buhoro buhoro mu mezi akurikira.',
    noteTitle: 'Icyitonderwa',
    noteText: 'Kwishyura iminsi ikurikirana cyangwa kuyigabanya bishobora kubonwa ukundi bitewe n’ishuri ry’amategeko; nta buryo bwombi bugaragazwa hano nk’ubwonyine bwemewe.',
    recordTips: [
      'Andika umubare wose w’iminsi yo kwishyura Ramadan irangiye',
      'Hitamo uburyo bworoshye: kalendari, porogaramu, ikayi',
      'Shyira ikimenyetso ku munsi wose wishyuwe',
    ],
    section1Body3: 'Urugero, umuntu ufite iminsi 6 yo kwishyura ashobora guhitamo kwiyiriza umwe buri cyumweru mu byumweru bitandatu, cyangwa kuyihuriza hamwe mu gihe kimwe niba bimubereye.',
    section2Body: 'Ni ibisanzwe kugerageza kwishyura iminsi watakaje mbere ya Ramadan ikurikira. Ibi ntibitegetswe buri gihe mu bihe byose, ariko byoroshya gutegura kandi birinda kwirundanya k’iminsi myinshi itarishyurwa.',
    visual1Title: 'Umuvuduko uhuza nawe',
    visual1Text: 'Kugabanya iminsi yo kwishyura hakurikijwe gahunda yawe bigufasha gukomeza utuje, nta gahato.',
    section2Body2: 'Gutegura hakiri kare bifasha kwirinda guhangayika mu minota ya nyuma. Inama yoroshye ni ukubara iminsi isigaye mbere ya Ramadan ikurikira no kugabanya iminsi yo kwishyura mu byumweru cyangwa amezi asigaye.',
    tip1Title: 'Ni byiza kubimenya',
    tip1Text: 'Niba impamvu ihoraho cyangwa isubiramo ibuza kwiyiriza (uburwayi bumara igihe, urugero), imiterere ishobora kugengwa n’andi mategeko; icyo gihe ni ingirakamaro cyane kubiganiraho n’umuhanga ubifitiye ububasha.',
    alert2Title: 'Amakuru y’ingenzi',
    alert2Text: 'Amategeko yihariye iyo igihe kirenze ashobora gutandukana bitewe n’uko basobanura. Ku kibazo cyose gikomeye, igitekerezo cy’umuhanga ubifitiye ububasha gikomeza kuba igisubizo.',
    section2Body3: 'Urugero, niba Ramadan ikurikira itangira mu mezi 8 kandi hasigaye iminsi 6 yo kwishyura, uburyo bumwe ni ugutegura umunsi umwe hafi buri kwezi, ukareka umwanya w’ibitunguranye.',
    section3Body: 'Inda no konsa bishobora kugira ingaruka ku bushobozi bwo kwiyiriza, cyane cyane iyo kwiyiriza bishyira mu kaga ubuzima bw’umubyeyi cyangwa bw’umwana. Imibereho myiza y’umubiri n’ubushobozi nyabwo bwo kwiyiriza ni ibintu by’ingenzi byo kuzirikana.',
    visual2Title: 'Imiterere yitabwaho',
    visual2Text: 'Iyi miterere imenyekana n’imigenzo y’idini nk’ishobora gutuma habaho kubabarirwa.',
    section3Body2: 'Ibitekerezo by’idini ku kutiyiriza mu gihe cy’inda cyangwa konsa bishobora gutandukana bitewe n’ishuri, cyane cyane ku kibazo cy’uko kwishyura gusa bihagije cyangwa niba hari n’indishyi. Impamvu nyayo yo kutiyiriza n’imiterere bwite bishobora kugira ingaruka ku gisubizo gikwiye.',
    tip2Title: 'Ni byiza kubimenya',
    tip2Text: 'Qadaa igufasha kwishyura utuje iminsi y’isiyamu watakaje, ku muvuduko wawe. Mu miterere yihariye (igihe cyarenze, inda, konsa, inzitizi ihoraho), igitekerezo cy’umuhanga ubifitiye ububasha gikomeza kuba isoko nziza.',
    shareMessage: 'Kwiyiriza no kubabarirwa: kwishyura (Qadaa) — AWA',
  },
