    section1Body3: 'მაგალითად, ადამიანს, რომელსაც 6 დღის ანაზღაურება აქვს, შეუძლია ექვსი კვირის განმავლობაში კვირაში ერთი დღე იმარხულოს ან დღეები ერთ პერიოდში გააერთიანოს, თუ ეს უფრო მოუხდება.',
