    section1Body: 'Qadha merujuk kepada penggantian, pada masa kemudian, hari puasa yang terlepas semasa Ramadan — terutamanya kerana haid. Hari-hari ini mesti diganti kerana puasa Ramadan kekal sebagai tonggak bulan itu, dan hari yang ditangguhkan kerana haid dikira sebagai hutang, tanpa ini menjadi kesalahan anda.',
    section1Body2: 'Penggantian biasanya boleh bermula sebaik sahaja Ramadan berakhir, apabila keadaan anda mengizinkan. Anda boleh menyusun hari-hari ini mengikut rentak anda: sesetengah orang lebih suka menghimpunkannya sejurus selepas Ramadan, manakala yang lain menyebarkannya secara beransur-ansur sepanjang bulan-bulan berikutnya.',
