    section1Body: 'Ang Qadaa ay tumutukoy sa pagbawi, sa ibang pagkakataon, ng mga araw ng pag-aayuno na hindi nagawa sa Ramadan — lalo na dahil sa regla. Dapat bawiin ang mga araw na ito dahil nananatiling haligi ng buwan ang pag-aayuno sa Ramadan, at ang mga araw na naipagpaliban dahil sa regla ay itinuturing na utang, nang hindi mo ito kasalanan.',
    section1Body2: 'Karaniwang maaaring simulan ang pagbawi sa sandaling matapos ang Ramadan, kapag pinahihintulutan ng iyong sitwasyon. Maaari mong ayusin ang mga araw na ito sa sarili mong bilis: may mga mas gustong pagsama-samahin ang mga ito pagkatapos ng Ramadan, habang ang iba ay unti-unting ipinamamahagi sa mga sumunod na buwan.',
