    section1Body: 'કઝા એટલે રમઝાન દરમિયાન ચૂકેલા રોઝાના દિવસો પછીથી પૂરા કરવા — ખાસ કરીને માસિકને કારણે ચૂકેલા દિવસો. આ દિવસો પૂરા કરવા જરૂરી છે, કારણ કે રમઝાનનો રોઝો આ મહિનાનો એક સ્તંભ છે, અને માસિકને કારણે અટકેલા દિવસો બાકી ગણાય છે, તેમાં તમારી કોઈ ભૂલ નથી.',
    section1Body2: 'રમઝાન પૂરો થતાં જ, તમારી પરિસ્થિતિ અનુકૂળ હોય ત્યારે સામાન્ય રીતે કઝા શરૂ કરી શકાય છે. આ દિવસોનું આયોજન તમે તમારી ગતિએ કરી શકો છો: કેટલાક લોકો રમઝાન પછી તરત જ બધા દિવસો સાથે રાખવાનું પસંદ કરે છે, જ્યારે બીજા લોકો પછીના મહિનાઓમાં ધીમે ધીમે ફેલાવીને રાખે છે.',
