    section1Body3: 'ઉદાહરણ તરીકે, જેને 6 દિવસ પૂરા કરવાના હોય તે છ અઠવાડિયા સુધી અઠવાડિયે એક રોઝો રાખી શકે છે, અથવા જો અનુકૂળ હોય તો તે બધા એક જ સમયગાળામાં સાથે રાખી શકે છે.',
    section2Body: 'આવતા રમઝાન પહેલાં ચૂકેલા દિવસો પૂરા કરવાનો પ્રયાસ કરવો સામાન્ય છે. દરેક કિસ્સામાં આ પ્રથા નિયમિત રીતે ફરજિયાત નથી, પરંતુ તેનાથી આયોજન સરળ બને છે અને બાકી દિવસોનો મોટો ઢગલો ભેગો થતો અટકે છે.',
    visual1Title: 'તમને અનુકૂળ ગતિ',
