    section2Body2: 'આગળથી આયોજન કરવાથી છેલ્લી ઘડીનો તણાવ ટાળી શકાય છે. એક સરળ સૂચન: આવતા રમઝાન સુધી બાકી રહેલા દિવસોની ગણતરી કરો અને પૂરા કરવાના દિવસોને ઉપલબ્ધ અઠવાડિયાં કે મહિનાઓમાં વહેંચી દો.',
