    section2Body3: 'ઉદાહરણ તરીકે, જો આવતો રમઝાન 8 મહિનામાં શરૂ થતો હોય અને 6 દિવસ પૂરા કરવાના બાકી હોય, તો એક શક્યતા એ છે કે દર મહિને લગભગ એક દિવસનું આયોજન કરવું, અને અણધારી પરિસ્થિતિઓ માટે લવચીકતા રાખવી.',
    section3Body: 'ગર્ભાવસ્થા અને સ્તનપાન રોઝા રાખવાની ક્ષમતા પર અસર કરી શકે છે, ખાસ કરીને જ્યારે રોઝા રાખવાથી માતા કે બાળકના આરોગ્યને જોખમ હોય. શારીરિક સુખાકારી અને રોઝા રાખવાની વાસ્તવિક ક્ષમતા ધ્યાનમાં લેવાના મહત્વના પરિબળો છે.',
    visual2Title: 'ધ્યાનમાં લેવાતી પરિસ્થિતિ',
    visual2Text: 'ધાર્મિક પરંપરા આ સંજોગોને છૂટ મળવાની શક્યતા ધરાવતા ગણે છે.',
    section3Body2: 'ગર્ભાવસ્થા કે સ્તનપાન દરમિયાન ન રાખેલા રોઝા અંગે ધાર્મિક અભિપ્રાયો શાખા પ્રમાણે જુદા હોઈ શકે છે, ખાસ કરીને એ પ્રશ્ન પર કે માત્ર કઝા પૂરતી છે કે તેની સાથે વળતર પણ સામેલ છે. રોઝા ન રાખવાનું ચોક્કસ કારણ અને વ્યક્તિગત પરિસ્થિતિ લાગુ પડતા જવાબને અસર કરી શકે છે.',
    tip2Title: 'જાણવા જેવું',
    tip2Text: 'કઝા તમને ચૂકેલા રોઝા શાંતિથી, તમારી પોતાની ગતિએ પૂરા કરવાની તક આપે છે. કોઈ ખાસ પરિસ્થિતિમાં (સમયમર્યાદા વટી જવી, ગર્ભાવસ્થા, સ્તનપાન, લાંબા ગાળાનો અવરોધ) લાયક વિદ્વાનનો અભિપ્રાય શ્રેષ્ઠ સ્ત્રોત રહે છે.',
