    intro: 'ਛੁੱਟੇ ਹੋਏ ਰੋਜ਼ਿਆਂ ਦੀ ਕਜ਼ਾ ਕਿਵੇਂ ਅਤੇ ਕਦੋਂ ਕਰਨੀ ਹੈ, ਆਪਣੀ ਰਫ਼ਤਾਰ ਨਾਲ ਅਤੇ ਬਿਨਾਂ ਕਿਸੇ ਦੋਸ਼-ਭਾਵਨਾ ਦੇ।',
    disclaimerTitle: 'ਜ਼ਰੂਰੀ ਜਾਣਕਾਰੀ',
    disclaimerText: 'ਇਹ ਸਮੱਗਰੀ ਸਿਰਫ਼ ਸਿੱਖਿਆ ਲਈ ਹੈ। ਧਾਰਮਿਕ ਸਵਾਲਾਂ ਦੀ ਪੁਸ਼ਟੀ ਯੋਗ ਵਿਦਵਾਨਾਂ ਤੋਂ ਕਰਵਾਉਣੀ ਚਾਹੀਦੀ ਹੈ। AWA ਫ਼ਤਵੇ ਜਾਂ ਨਿੱਜੀ ਧਾਰਮਿਕ ਫ਼ੈਸਲੇ ਜਾਰੀ ਨਹੀਂ ਕਰਦਾ।',
