    section1Body3: 'ဥပမာ၊ ပြန်ဆောင်ရွက်ရမည့်ရက် 6 ရက်ရှိသူတစ်ဦးသည် တစ်ပတ်လျှင် တစ်ရက်ကို ခြောက်ပတ်ကြာ ရိုဇာဆောင်နိုင်သည်၊ သို့မဟုတ် ပိုသင့်တော်လျှင် တစ်ကာလတည်းတွင် စုပေါင်း၍ ဆောင်နိုင်သည်။',
    section2Body: 'လွတ်သွားသောရက်များကို နောက်ရမဇာန်မတိုင်မီ ပြန်ဆောင်ရွက်ရန် ကြိုးစားလေ့ရှိကြသည်။ ဤအလေ့အထသည် အမှုတိုင်းတွင် စနစ်တကျ မဖြစ်မနေ လိုအပ်သည်မဟုတ်သော်လည်း စီစဉ်ရလွယ်ကူစေပြီး ကျန်ရှိနေသော ရက်များ အများအပြား စုပုံမလာစေရန် ကူညီသည်။',
    visual1Title: 'သင့်အတွက် ကိုက်ညီသော အရှိန်',
    visual1Text: 'ပြန်ဆောင်ရွက်ရမည့်ရက်များကို သင့်အချိန်ဇယားနှင့်အညီ ခွဲဝေလိုက်ခြင်းဖြင့် ဖိအားမရှိဘဲ ငြိမ်သက်စွာ ရှေ့ဆက်နိုင်သည်။',
    section2Body2: 'ကြိုတင်စီစဉ်ခြင်းသည် နောက်ဆုံးအချိန်ရောက်မှ စိတ်ဖိစီးမှုကို ရှောင်ရှားရန် ကူညီသည်။ ရိုးရှင်းသော အကြံပြုချက်မှာ နောက်ရမဇာန်မတိုင်မီ ကျန်ရှိသောရက်အရေအတွက်ကို ရေတွက်ပြီး ပြန်ဆောင်ရွက်ရမည့်ရက်များကို ရရှိနိုင်သော ရက်သတ္တပတ် သို့မဟုတ် လများအတွင်း ခွဲဝေခြင်း ဖြစ်သည်။',
    tip1Title: 'သိထားသင့်သည်',
    tip1Text: 'ရိုဇာမဆောင်နိုင်စေသော ကြာရှည်ခံ သို့မဟုတ် ထပ်ခါတလဲလဲဖြစ်သည့် အကြောင်းရင်းရှိလျှင် (ဥပမာ - ကြာရှည်စွာ ဖြစ်ပေါ်နေသော ကျန်းမာရေးအခြေအနေ) ထိုအခြေအနေသည် မတူညီသော မူဘောင်တစ်ခုအောက်သို့ ကျရောက်နိုင်သည်၊ ထိုအခါ အရည်အချင်းပြည့်မီသော ပညာရှင်နှင့် ဆွေးနွေးခြင်းသည် အထူးအသုံးဝင်သည်။',
    alert2Title: 'အရေးကြီးသော အချက်အလက်',
    alert2Text: 'သတ်မှတ်ကာလကို ကျော်လွန်သွားလျှင် တိကျသော စည်းမျဉ်းများသည် အနက်ဖွင့်ဆိုမှုအလိုက် ကွဲပြားနိုင်သည်။ ရှုပ်ထွေးသော အခြေအနေတိုင်းတွင် အရည်အချင်းပြည့်မီသော ပညာရှင်၏ ထင်မြင်ချက်သည် ကိုးကားရန် အခြေခံဖြစ်သည်။',
    section2Body3: 'ဥပမာ၊ နောက်ရမဇာန်သည် 8 လအကြာတွင် စတင်ပြီး ပြန်ဆောင်ရွက်ရန် 6 ရက်ကျန်လျှင် မမျှော်လင့်ထားသော အခြေအနေများအတွက် ပြောင်းလွယ်ပြင်လွယ်ရှိစွာဖြင့် တစ်လလျှင် တစ်ရက်ခန့် စီစဉ်ထားခြင်းသည် တစ်ဖြစ်နိုင်ချေဖြစ်သည်။',
    section3Body: 'ကိုယ်ဝန်ဆောင်ခြင်းနှင့် နို့တိုက်ခြင်းသည် ရိုဇာဆောင်နိုင်စွမ်းကို သက်ရောက်နိုင်သည်၊ အထူးသဖြင့် ရိုဇာဆောင်ခြင်းက မိခင် သို့မဟုတ် ကလေး၏ ကျန်းမာရေးကို အန္တရာယ်ရှိစေသည့်အခါ ဖြစ်သည်။ ရုပ်ပိုင်းဆိုင်ရာ ကျန်းမာချမ်းသာမှုနှင့် ရိုဇာဆောင်နိုင်စွမ်းအမှန်သည် ထည့်သွင်းစဉ်းစားရမည့် အရေးကြီးသော အချက်များ ဖြစ်သည်။',
    visual2Title: 'ထည့်သွင်းစဉ်းစားပေးသော အခြေအနေ',
    visual2Text: 'ဤအခြေအနေများသည် ကင်းလွတ်ခွင့်ရနိုင်ဖွယ်ရှိကြောင်း ဘာသာရေးအစဉ်အလာက အသိအမှတ်ပြုထားသည်။',
    section3Body2: 'ကိုယ်ဝန်ဆောင်စဉ် သို့မဟုတ် နို့တိုက်စဉ် မဆောင်နိုင်ခဲ့သော ရိုဇာနှင့်ပတ်သက်သည့် ဘာသာရေးထင်မြင်ချက်များသည် မဇ်ဟဗ်အလိုက် ကွဲပြားနိုင်သည်၊ အထူးသဖြင့် ရိုးရိုးပြန်ဆောင်ရွက်ရုံ လုံလောက်ပါသလား သို့မဟုတ် လျော်ကြေးတစ်ခုပါ ပါဝင်ပါသလားဆိုသည့် မေးခွန်းတွင် ဖြစ်သည်။ ရိုဇာမဆောင်ရသည့် တိကျသောအကြောင်းရင်းနှင့် ကိုယ်ရေးကိုယ်တာ အခြေအနေသည် သက်ဆိုင်သော အဖြေကို သက်ရောက်နိုင်သည်။',
    tip2Title: 'သိထားသင့်သည်',
    tip2Text: 'ကဇာသည် လွတ်သွားသော ရိုဇာရက်များကို ကိုယ့်အရှိန်အတိုင်း ငြိမ်သက်စွာ ပြန်ဆောင်ရွက်ခွင့်ပေးသည်။ ထူးခြားသော အခြေအနေရှိလျှင် (ကာလကျော်လွန်ခြင်း၊ ကိုယ်ဝန်ဆောင်ခြင်း၊ နို့တိုက်ခြင်း၊ ကြာရှည်ခံ အဟန့်အတားရှိခြင်း) အရည်အချင်းပြည့်မီသော ပညာရှင်၏ ထင်မြင်ချက်သည် အကောင်းဆုံး အရင်းအမြစ် ဖြစ်သည်။',
