    section2Body2: 'ការរៀបចំទុកជាមុនជួយជៀសវាងភាពតានតឹងនៅនាទីចុងក្រោយ។ គន្លឹះសាមញ្ញមួយគឺរាប់ចំនួនថ្ងៃដែលនៅសល់មុនរ៉ាម៉ាដានបន្ទាប់ ហើយបែងចែកថ្ងៃដែលត្រូវបួសសងលើសប្តាហ៍ ឬខែដែលមាន។',
    tip1Title: 'គួរដឹង',
    tip1Text: 'ប្រសិនបើមូលហេតុដែលបន្ត ឬកើតឡើងម្តងហើយម្តងទៀតរារាំងការបួស (ឧទាហរណ៍ ស្ថានភាពសុខភាពរយៈពេលយូរ) ស្ថានភាពនោះអាចស្ថិតក្នុងក្របខ័ណ្ឌផ្សេង ហើយការពិភាក្សាជាមួយអ្នកប្រាជ្ញសាសនាដែលមានគុណវុឌ្ឍិមានប្រយោជន៍ជាពិសេស។',
    alert2Title: 'ព័ត៌មានសំខាន់',
    alert2Text: 'ច្បាប់ច្បាស់លាស់ក្នុងករណីហួសកាលកំណត់អាចខុសគ្នាអាស្រ័យលើការបកស្រាយ។ សម្រាប់ស្ថានភាពស្មុគស្មាញណាមួយ មតិរបស់អ្នកប្រាជ្ញសាសនាដែលមានគុណវុឌ្ឍិនៅតែជាឯកសារយោង។',
    section2Body3: 'ឧទាហរណ៍ ប្រសិនបើរ៉ាម៉ាដានបន្ទាប់ចាប់ផ្តើមក្នុងរយៈពេល 8 ខែ ហើយនៅសល់ 6 ថ្ងៃត្រូវបួសសង លទ្ធភាពមួយគឺគ្រោងបួសប្រហែលមួយថ្ងៃក្នុងមួយខែ ដោយមានភាពបត់បែនសម្រាប់ករណីមិនបានរំពឹងទុក។',
    section3Body: 'ការមានផ្ទៃពោះ និងការបំបៅដោះអាចប៉ះពាល់ដល់សមត្ថភាពក្នុងការបួស ជាពិសេសនៅពេលដែលការបួសបង្កហានិភ័យដល់សុខភាពរបស់ម្តាយ ឬកូន។ សុខុមាលភាពរាងកាយ និងសមត្ថភាពពិតប្រាកដក្នុងការបួស គឺជាកត្តាសំខាន់ដែលត្រូវយកមកពិចារណា។',
    visual2Title: 'ស្ថានភាពដែលត្រូវបានគេយកមកពិចារណា',
    visual2Text: 'ប្រពៃណីសាសនាទទួលស្គាល់ថា ស្ថានភាពទាំងនេះអាចផ្តល់ហេតុនាំឱ្យមានការលើកលែង។',
    section3Body2: 'មតិខាងសាសនាអំពីការបួសដែលមិនបានធ្វើក្នុងអំឡុងពេលមានផ្ទៃពោះ ឬបំបៅដោះ អាចខុសគ្នាអាស្រ័យលើសាលា ជាពិសេសលើសំណួរថាតើការបួសសងសាមញ្ញគ្រប់គ្រាន់ ឬក៏ត្រូវមានសំណងបន្ថែមដែរ។ មូលហេតុច្បាស់លាស់នៃការមិនបួស និងស្ថានភាពផ្ទាល់ខ្លួន អាចជះឥទ្ធិពលលើចម្លើយដែលអនុវត្តបាន។',
    tip2Title: 'គួរដឹង',
    tip2Text: 'កាហ្សា អនុញ្ញាតឱ្យអ្នកបួសសងថ្ងៃដែលខកខានដោយស្ងប់ស្ងាត់ តាមល្បឿនរបស់អ្នកផ្ទាល់។ ក្នុងករណីស្ថានភាពពិសេស (ហួសកាលកំណត់ ការមានផ្ទៃពោះ ការបំបៅដោះ ឧបសគ្គរយៈពេលយូរ) មតិរបស់អ្នកប្រាជ្ញសាសនាដែលមានគុណវុឌ្ឍិនៅតែជាធនធានដ៏ល្អបំផុត។',
    shareMessage: 'ការបួស និងការលើកលែង៖ ការបួសសងវិញ (កាហ្សា) — AWA',
