    disclaimerTitle: 'ຂໍ້ມູນສຳຄັນ',
    disclaimerText: 'ເນື້ອຫານີ້ມີຈຸດປະສົງເພື່ອການສຶກສາເທົ່ານັ້ນ. ຄຳຖາມທາງສາສະໜາຄວນໄດ້ຮັບການຢືນຢັນຈາກນັກປາດສາສະໜາທີ່ມີຄຸນວຸດທິ. AWA ບໍ່ອອກຟັດວາ ຫຼື ຄຳຕັດສິນທາງສາສະໜາສະເພາະບຸກຄົນ.',
