    section1Body: 'ກະຊາ ໝາຍເຖິງການຖືສິນອົດຊົດໃນພາຍຫຼັງ ສຳລັບມື້ທີ່ຂາດໄປໃນເດືອນຣອມະດອນ — ໂດຍສະເພາະຍ້ອນປະຈຳເດືອນ. ມື້ເຫຼົ່ານີ້ຕ້ອງຖືສິນອົດຊົດ ເພາະການຖືສິນອົດໃນເດືອນຣອມະດອນຍັງເປັນເສົາຫຼັກຂອງເດືອນນັ້ນ ແລະ ມື້ທີ່ຖືກຢຸດໄວ້ຍ້ອນປະຈຳເດືອນຖືວ່າເປັນມື້ທີ່ຕ້ອງຊົດ ໂດຍບໍ່ແມ່ນຄວາມຜິດຂອງທ່ານແຕ່ຢ່າງໃດ.',
    section1Body2: 'ໂດຍທົ່ວໄປສາມາດເລີ່ມຊົດໄດ້ທັນທີທີ່ຣອມະດອນສິ້ນສຸດລົງ ເມື່ອສະຖານະການຂອງທ່ານອະນຸຍາດ. ທ່ານສາມາດຈັດແຈງມື້ເຫຼົ່ານີ້ຕາມຈັງຫວະຂອງທ່ານເອງ: ບາງຄົນມັກລວມຖືຕິດກັນຫຼັງຈາກຣອມະດອນບໍ່ດົນ ໃນຂະນະທີ່ບາງຄົນຄ່ອຍໆກະຈາຍໄປຕະຫຼອດຫຼາຍເດືອນຕໍ່ມາ.',
