    section1Body3: 'ຕົວຢ່າງ, ຜູ້ທີ່ມີ 6 ມື້ຕ້ອງຊົດ ສາມາດເລືອກຖືອາທິດລະ 1 ມື້ເປັນເວລາ 6 ອາທິດ ຫຼື ລວມຖືໃນຊ່ວງດຽວກັນ ຖ້າເຫັນວ່າເໝາະສົມກວ່າ.',
    section2Body: 'ເປັນເລື່ອງທົ່ວໄປທີ່ຈະພະຍາຍາມຖືຊົດມື້ທີ່ຂາດກ່ອນຣອມະດອນຮອບຕໍ່ໄປ. ການປະຕິບັດນີ້ບໍ່ໄດ້ເປັນການບັງຄັບທຸກກໍລະນີ ແຕ່ຊ່ວຍໃຫ້ຈັດແຈງງ່າຍຂຶ້ນ ແລະ ຫຼີກເວັ້ນການສະສົມມື້ຄ້າງຈຳນວນຫຼາຍ.',
    visual1Title: 'ຈັງຫວະທີ່ປັບໃຫ້ເຂົ້າກັບທ່ານ',
    visual1Text: 'ການກະຈາຍມື້ທີ່ຕ້ອງຊົດຕາມຕາຕະລາງຂອງທ່ານ ຊ່ວຍໃຫ້ທ່ານກ້າວໄປຂ້າງໜ້າຢ່າງສະຫງົບ ໂດຍບໍ່ມີຄວາມກົດດັນ.',
    section2Body2: 'ການວາງແຜນລ່ວງໜ້າຊ່ວຍຫຼີກເວັ້ນຄວາມກັງວົນໃນນາທີສຸດທ້າຍ. ເຄັດລັບງ່າຍໆຄືນັບຈຳນວນມື້ທີ່ເຫຼືອກ່ອນຣອມະດອນຮອບຕໍ່ໄປ ແລ້ວກະຈາຍມື້ທີ່ຕ້ອງຊົດໄປຕາມອາທິດ ຫຼື ເດືອນທີ່ມີ.',
    tip1Title: 'ຄວນຮູ້',
